"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[2565],{8687(e){e.exports=JSON.parse('{"tag":{"label":"Backtracking","permalink":"/concepts/tags/backtracking","allTagsPath":"/concepts/tags","count":6,"items":[{"id":"backtracking/classic-problems","title":"Backtracking: Classic Problems","description":"This lesson applies the general schemes of backtracking to a series of classic problems. They are ordered from simple to more demanding, and each one illustrates a different aspect of the paradigm:","permalink":"/concepts/backtracking/classic-problems"},{"id":"synthesis/choosing-a-technique","title":"Choosing a Design Technique","description":"You have now seen six design techniques you have a problem, and you must decide which technique to use.","permalink":"/concepts/synthesis/choosing-a-technique"},{"id":"backtracking/exercises","title":"Exercises: Backtracking","description":"These exercises review the two lessons on backtracking. They are different from the seminar activities (paths, Hamiltonian cycles and the traveling salesman) and from the lab problems, which are left for those sessions. Try each one before reading its solution: the solutions are grouped at the end of the page.","permalink":"/concepts/backtracking/exercises"},{"id":"backtracking/proofs","title":"Proofs: Backtracking","description":"Backtracking is an exact method: it promises to find every solution, or the best one. That promise depends on the pruning being safe, that is, never discarding a branch that contains what we are looking for. This page proves when that is the case.","permalink":"/concepts/backtracking/proofs"},{"id":"backtracking/summary","title":"Summary: Backtracking","description":"Everything on one page, to review the chapter before moving on.","permalink":"/concepts/backtracking/summary"},{"id":"backtracking/backtracking-scheme","title":"The Backtracking Scheme","description":"Some problems resist every technique seen so far. There is no greedy criterion that guarantees the optimum, the problem does not split into independent halves, and there is no small table of subproblems to fill. Very often the only way to be sure of the answer is to examine the candidate solutions one by one. Backtracking is the paradigm that organizes that examination so that it is systematic (no candidate is forgotten) and as cheap as possible (whole families of candidates are discarded at once).","permalink":"/concepts/backtracking/backtracking-scheme"}],"unlisted":false}}')}}]);